// Perintah terminal kompilasi dan eksekusi
// 1. Kompilasi:
javac ProgramUtama.java

// 2. Eksekusi:
java ProgramUtama

public class Mobil {
    // Atribut (State)
    String warna;
    int kecepatan;

    // Method (Behavior)
    void tambahKecepatan(int akselerasi) {
        kecepatan += akselerasi;
    }

    public static void main(String[] args) {
        // Instansiasi Objek
        Mobil mobilSaya = new Mobil();
        mobilSaya.warna = "Merah";
        mobilSaya.tambahKecepatan(20);
        System.out.println(mobilSaya.warna + " kecepatan: " + mobilSaya.kecepatan);
    }
}

public class AkunBank {
    public static int totalAkun = 0; // Class variable (static)
    private double saldo;            // Instance variable

    public void deposit(double jumlah) { // Local variable: jumlah
        double bonus = 5000;             // Local variable
        saldo += (jumlah + bonus);
    }
}

