public class SegiEmpat {
    private double panjang;
    private double lebar;

    public SegiEmpat(double panjang, double lebar) {
        this.panjang = panjang;
        this.lebar = lebar;
    }

    public void setPanjang(double panjang) {
        if (panjang > 0) {
            this.panjang = panjang; // Validasi nilai positif
        }
    }

    public double getPanjang() {
        return this.panjang;
    }
}

public class Sepeda {
    protected int kecepatan;
    public void setKecepatan(int k) { this.kecepatan = k; }
}

public class SepedaGunung extends Sepeda {
    private int sadel;
    public void setSadel(int s) { this.sadel = s; }
}

public class Person {
    private String name;
    public Person(String name) {
        this.name = name;
    }
}

public class Student extends Person {
    private String nim;
    public Student(String name, String nim) {
        super(name); // Wajib baris pertama!
        this.nim = nim;
    }
}

public class Pegawai {
    protected String nama;
    protected double gaji;
}

public class Manajer extends Pegawai {
    public void naikkanGaji(double persen) {
        this.gaji += (this.gaji * persen / 100); // Valid karena gaji bertipe protected
    }
}

public class Lingkaran {
    // Method 1: tanpa parameter
    public void gambarLingkaran() {
        System.out.println("Menggambar lingkaran default");
    }

    // Method 2: overloaded dengan parameter int
    public void gambarLingkaran(int diameter) {
        System.out.println("Menggambar lingkaran diameter: " + diameter);
    }
}

public class Sepeda {
    public void setGir(int pertambahanGir) {
        // Logika dasar
    }
}

public class SepedaGunung extends Sepeda {
    @Override
    public void setGir(int pertambahanGir) {
        super.setGir(pertambahanGir); // Panggil implementasi parent
        System.out.println("Gir khusus sepeda gunung diterapkan");
    }
}

